DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM instrumento_procedimento_config WHERE serie_dr IS NULL) THEN
        RAISE EXCEPTION 'Há configurações de Procedimento sem série do DR: atribua-lhes uma série ou apague-as antes de repor instrumento_procedimento_config.serie_dr NOT NULL.';
    END IF;
END $$;
